def get_total_number_of_sequences(m, n):
    if n == 1:
        return m

    count = [0] * (m + 2)

    def solve(current_val, length_left):
        nonlocal count

        # Base case: no more elements to add
        if length_left == 0:
            count[current_val] += 1
            return

        for next_val in range(2 * current_val, m + 1):
            solve(next_val, length_left - 1)

    solve(1, n - 1)
    return sum(count[1:])

